</style></head><body><header class="shell top"><a href="/"><?= $escape($brandName) ?></a></header><main class="shell"><h1>Model workspace and privacy rights.</h1><p class="intro">Use your application reference and application email to access privacy rights or the model workspace. A one-time email code is required before any application information is shown or changed. Workspace sessions expire after 30 minutes; legal holds may restrict portfolio mutations.</p><section class="panel"><?php if($error!==''):?><div class="alert error" role="alert"><?= $escape($error) ?></div><?php endif;?><?php if($notice!==''):?><div class="alert success" role="status"><?= $escape($notice) ?></div><?php endif;?>
<?php if($screen==='request'):?><form method="post" action="/model-agency/privacy"><input type="hidden" name="_csrf" value="<?= $escape($csrf) ?>"><div class="field"><label for="reference">Application reference</label><input id="reference" name="reference" maxlength="32" required></div><div class="field"><label for="email">Application email address</label><input id="email" name="email" type="email" maxlength="254" required></div><div class="field"><label for="request_type">Request type</label><select id="request_type" name="request_type"><option value="access">Access my information</option><option value="correction">Correct my information</option><option value="withdrawal">Withdraw my application</option><option value="erasure">Request erasure</option><option value="portfolio_withdrawal">Withdraw a portfolio image</option><option value="portal_access">Open my model workspace</option></select></div><div class="field"><label for="asset_id">Portfolio asset ID (only for image withdrawal)</label><input id="asset_id" name="asset_id" maxlength="36" pattern="[0-9a-fA-F-]{36}"><p class="hint">First use “Access my information” to view your portfolio asset IDs. Leave blank for other request types.</p></div><button class="button" type="submit">Send verification code</button></form>
<?php elseif($screen==='verify'):?><form method="post" action="/model-agency/privacy/verify"><input type="hidden" name="_csrf" value="<?= $escape($csrf) ?>"><div class="field"><label for="code">Eight-digit email verification code</label><input id="code" name="code" inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]{8}" maxlength="8" required></div><button class="button" type="submit">Verify and continue</button></form><p class="hint">If the application reference and email match an active record, a code will be sent. Codes expire after 10 minutes. A verified model workspace session lasts up to 30 minutes.</p>
<?php elseif($screen==='access'):?><div class="alert success">Your verified application record is shown below.</div><?php foreach(['application_reference'=>'Application reference','applicant_name'=>'Applicant name','email'=>'Email','phone'=>'Phone','country_code'=>'Country','city'=>'City','portfolio_url'=>'Portfolio','experience_summary'=>'Experience summary','status'=>'Status','privacy_notice_version'=>'Privacy notice version','privacy_acknowledged_at'=>'Privacy acknowledgement','created_at'=>'Submitted'] as $key=>$label):?><div class="record"><strong><?= $escape($label) ?></strong><span><?= $escape($record[$key]??'') ?></span></div><?php endforeach;?><?php if(is_array($record['portfolio_assets']??null) && count($record['portfolio_assets'])>0):?><h2>Portfolio assets</h2><p class="hint">Use an asset ID below to request withdrawal of that specific image. Withdrawal removes its private file and invalidates dependent usage licences and casting submissions.</p><?php foreach($record['portfolio_assets'] as $asset):?><div class="record"><strong>Asset ID</strong><span><?= $escape($asset['id']??'') ?></span></div><div class="record"><strong>Status</strong><span><?= $escape($asset['status']??'') ?></span></div><?php endforeach;?><?php else:?><p class="hint">No portfolio assets are currently recorded for this application.</p><?php endif;?>
